import Link from 'next/link';
import {notFound} from 'next/navigation';
import {requireAdmin} from '@/lib/auth';
import {prisma} from '@/lib/prisma';
import {reviewVendorApplication} from '../../actions';
export const dynamic='force-dynamic';
export default async function VendorApplication({params}:{params:Promise<{id:string}>}){await requireAdmin();const {id}=await params;const app=await prisma.vendorApplication.findUnique({where:{id},include:{applicant:true,reviewer:true}});if(!app)notFound();return <main className="admin-content"><Link href="/admin/vendors/applications" className="text-sm text-slate-400">← Applications</Link><p className="eyebrow mt-5">VENDOR APPLICATION</p><h1 className="admin-title">{app.storeName}</h1><div className="admin-panel mt-8 max-w-2xl space-y-3"><p><b>Applicant:</b> {app.applicant.name} · {app.applicant.email}</p><p><b>Type:</b> {app.sellerType}</p><p><b>Contact:</b> {app.contactEmail}</p><p><b>Portfolio:</b> {app.portfolioUrl||'—'}</p><p><b>Status:</b> {app.status}</p><p className="whitespace-pre-wrap text-slate-400">{app.storeDescription}</p>{app.businessInformation&&<p className="whitespace-pre-wrap text-slate-400">{app.businessInformation}</p>}<form action={reviewVendorApplication} className="mt-6 space-y-3 border-t border-white/10 pt-5"><input type="hidden" name="id" value={app.id}/><select className="form-input" name="decision" defaultValue={app.status==='SUBMITTED'?'UNDER_REVIEW':app.status}><option>UNDER_REVIEW</option><option>APPROVED</option><option>REJECTED</option></select><textarea className="form-input" name="note" placeholder="Reviewer note"/><button className="btn-primary">Save review</button></form></div></main>}
